con:testSuite.con:setupScript:
// --- Configuration --- 
def SLA_THRESHOLD = 1000  // milliseconds

// --- Iterate Over All Test Steps in the TestSuite ---
def testSuite = context.testSuite
def steps = testSuite.getTestCaseList().collect { it.getTestStepList() }.flatten()

// Initialize the SLA_FAILED flag
boolean slaFailed = false

steps.each { step ->
    // Only process HTTP/REST Test Steps and skip untested ones (steps with no response)
    if (!step.metaClass.respondsTo(step, "getTestRequest") || step.testRequest?.response == null) {
        log.warn "Step '${step.name}' is not a REST/HTTP Test Step or is untested. Skipping SLA check."
        return
    }

    def timeTaken = step.testRequest?.response?.timeTaken
    if (timeTaken != null && timeTaken > SLA_THRESHOLD) {
        def message = "SLA Warning: Step '${step.name}' took ${timeTaken}ms (threshold: ${SLA_THRESHOLD}ms)"
        log.warn(message)

        // --- Gather TestRail Properties ---
        def testCaseId = step.testCase.getPropertyValue("TestCaseID")
        def runId = testSuite.project.getPropertyValue("RunID")
        def user = testSuite.project.getPropertyValue("TestRailUserName")
        def key = testSuite.project.getPropertyValue("TestRailAPIkey")
        def url = testSuite.project.getPropertyValue("TestRailUrl")

        if (!testCaseId || !runId || !user || !key || !url) {
            log.error("Missing one or more TestRail properties.")
            return
        }

        def fullUrl = "${url}/add_result_for_case/${runId}/${testCaseId}"
        def payload = [status_id: 2, comment: message] // status_id: 2 means "Failed"

        try {
            def connection = new URL(fullUrl).openConnection()
            connection.setRequestMethod("POST")
            connection.doOutput = true
            connection.setRequestProperty("Content-Type", "application/json")
            connection.setRequestProperty("Authorization", "Basic " + "${user}:${key}".bytes.encodeBase64().toString())

            def writer = new OutputStreamWriter(connection.outputStream, "UTF-8")
            writer.write(groovy.json.JsonOutput.toJson(payload))
            writer.flush()
            writer.close()

            def responseCode = connection.responseCode
            def responseText = responseCode == 200 ? connection.inputStream.text : connection.errorStream?.text

            if (responseCode == 200) {
                log.info("TestRail updated for ${testCaseId}: ${responseCode}")
            } else {
                log.error("TestRail update failed: ${responseCode} | ${responseText}")
            }
        } catch (Exception e) {
            log.error("Exception: ${e.message}")
        }

        // Set the SLA_FAILED flag to true to mark the failure
        slaFailed = true
    } else {
        log.info "SLA met for step '${step.name}': ${timeTaken}ms"
    }
}

// Store the SLA_FAILED flag in the TestSuite to be used in the teardown
testSuite.setPropertyValue("SLA_FAILED", slaFailed.toString())
  log.info (testSuite.setPropertyValue("SLA_FAILED", slaFailed.toString()))
